export type SetupOpts = {
    name?: string;
    network?: string;
    force?: boolean;
    /**
     * `true` for a bare `--import`. A string means the caller wrote
     * `--import <key>` or `--import=<key>`: the option is declared with an
     * optional value precisely so that mistake is caught here and refused,
     * instead of Commander echoing the argument back in an "unknown option"
     * error or silently ignoring it and reading an empty stdin.
     */
    import?: boolean | string;
};
export declare function setupCommand(opts: SetupOpts): Promise<void>;
